  const m=date.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if(!m)throw Error('Data inválida na nota '+(i+1));
  return {date:m[3]+'-'+m[2]+'-'+m[1],supplier,invoice,order,amount:root.EngefexCurrency.parse(amount)};
