 const tr=document.createElement('tr');
 const vals=[data.date||'',data.supplier||'',data.invoice||'',data.order||'',data.amount?Number(data.amount).toFixed(2).replace('.',','):''];
 tr.innerHTML=vals.map((v,i)=>'<td><input '+(i===0?'type="date" ':'type="text" ')+'class="ms-invoice-field" data-col="'+i+'" style="width:100%;min-width:'+(i===1?'180':'80')+'px" value="'+h(v)+'"></td>').join('')+'<td><button type="button" class="button secondary ms-invoice-delete">Excluir</button></td>';
 tr.querySelector('.ms-invoice-delete').onclick=()=>{tr.remove();invoiceGridUpdate()};
 tr.querySelectorAll('input').forEach((input)=>{
 input.oninput=invoiceGridUpdate;
 input.onpaste=e=>{
  const clipboard=e.clipboardData?.getData('text/plain')||'';
  if(!clipboard.includes('\t')&&!clipboard.includes('\n'))return;
  const lines=clipboard.trim().split(/\r?\n/).map(line=>line.split('\t'));
  if(lines.length===1&&lines[0].length===1)return;
  e.preventDefault();
  const columns=[...tr.querySelectorAll('input')],start=Number(input.dataset.col);
  if(lines.some(line=>line.length+start>5)){api.toast('A colagem ultrapassa as cinco colunas.');return}
  const existing=[...body.querySelectorAll('tr')],idx=existing.indexOf(tr);
  lines.forEach((values,offset)=>{
   while(body.querySelectorAll('tr').length<=idx+offset)addInvoiceGridRow(id);
   const target=body.querySelectorAll('tr')[idx+offset];
   const cells=[...target.querySelectorAll('input')];
   values.forEach((value,col)=>{
    const dest=cells[start+col];let v=value.trim();
    if(dest.type==='date'){const match=v.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);if(match)v=match[3]+'-'+match[2]+'-'+match[1]}
    dest.value=v;
   });
  });
  invoiceGridUpdate();
 };
 });
